import { describe, expect, it } from "vitest";

import { getGradeHistoryForCourse } from "../src/gradeHistory";

describe("getGradeHistoryForCourse", () => {
  it("returns all grade records for a course that has never been renamed", () => {
    const result = getGradeHistoryForCourse("course-61a");
    const terms = result.map((r) => r.term).sort();
    expect(terms).toEqual(["Fall 2019", "Fall 2020", "Spring 2020"]);
  });

  it("returns an empty array for an unknown course id", () => {
    expect(getGradeHistoryForCourse("does-not-exist")).toEqual([]);
  });

  it("includes grade records filed under a course's OLD subject+number after a rename", () => {
    const result = getGradeHistoryForCourse("course-astron");
    const terms = result.map((r) => r.term).sort();
    // ASTRON 88 (old identity, 2 terms) + ASTRON 128 (current identity, 2 terms)
    expect(terms).toEqual([
      "Fall 2012",
      "Fall 2016",
      "Spring 2014",
      "Spring 2019",
    ]);
  });

  it("does not pull in an unrelated course's grades just because it shares a subject", () => {
    const result = getGradeHistoryForCourse("course-astron");
    expect(result).toHaveLength(4);
    expect(result.every((r) => r.number === "88" || r.number === "128")).toBe(
      true
    );
  });

  it("follows a course through MULTIPLE renames, not just the most recent one", () => {
    const result = getGradeHistoryForCourse("course-ethstd");
    const terms = result.map((r) => r.term).sort();
    expect(terms).toEqual([
      "Fall 2010", // LEGALST 21
      "Fall 2014", // AMERSTD 21AC
      "Fall 2016", // AMERSTD 21AC
      "Fall 2019", // ETHSTD 21AC
      "Fall 2021", // ETHSTD 21AC
    ]);
  });

  it("aggregates enrollment correctly across every past identity", () => {
    const result = getGradeHistoryForCourse("course-ethstd");
    const totalEnrolled = result.reduce((sum, r) => sum + r.enrolled, 0);
    expect(totalEnrolled).toBe(350);
  });
});
